CREATE TABLE IF NOT EXISTS `copywriters` (`user_id` MEDIUMINT UNSIGNED NOT NULL ,`type` ENUM( 'per_text', 'per_symbols' ) NOT NULL COMMENT 'рублей за текст, рублей за 1000 символов',`rate` SMALLINT UNSIGNED NOT NULL COMMENT 'рублей за единичу измерения',PRIMARY KEY ( `user_id` )) ENGINE = MYISAM CHARACTER SET utf8 COLLATE utf8_general_ci;CREATE TABLE IF NOT EXISTS `copywriters_tasks` (  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT 'номер задачи',  `doc_type` enum('category','product','city','special','brand','brand-category') NOT NULL COMMENT 'тип произвольного документа: товар, категория, бренд, город и тп',  `doc_id` mediumint(8) unsigned NOT NULL COMMENT 'ID конечного документа',  `field` varchar(255) NOT NULL COMMENT 'название поля, которое заполняет копирайтер',  `text` text NOT NULL COMMENT 'содержимое поля, написанное копирайтером',  `copywriter_id` mediumint(8) unsigned NOT NULL COMMENT 'user_id копирайтера',  `date_write` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'дата написания текста',  `status` enum('new','need_check','accepted','declined') NOT NULL COMMENT 'статус текущей задачи по написанию текста',  `moderator_id` mediumint(8) unsigned NOT NULL COMMENT 'user_id проверяющего',  `data_check` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'дата проверки',  `decline_reason` text NOT NULL COMMENT 'причина отказа, пишет проверяющий, чтобы копирайтер видел проблему',  `priority` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT 'чем выше - тем важнее задача',  PRIMARY KEY (`id`)) ENGINE=MyISAM DEFAULT CHARSET=utf8 AUTO_INCREMENT=1 ;